task_spec.prompt:
Implement minimax Tic-Tac-Toe in src/tictactoe.py.

WINS = [(0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6)]

def check_winner(board: list) -> str | None:
    for a,b,c in WINS:
        if board[a] and board[a] == board[b] == board[c]:
            return board[a]
    return None

def is_full(board: list) -> bool:
    return all(x is not None for x in board)

def minimax(board: list, player: str, maximizing: bool) -> int:
    winner = check_winner(board)
    if winner == 'X': return 10
    if winner == 'O': return -10
    if is_full(board): return 0
    opponent = 'O' if player == 'X' else 'X'
    scores = []
    for i in range(9):
        if board[i] is None:
            board[i] = player
            score = minimax(board, opponent, not maximizing)
            board[i] = None
            scores.append(score)
    return max(scores) if maximizing else min(scores)

def best_move(board: list, player: str) -> int:
    best = None
    best_score = float('-inf') if player == 'X' else float('inf')
    opponent = 'O' if player == 'X' else 'X'
    for i in range(9):
        if board[i] is None:
            board[i] = player
            score = minimax(board, opponent, player == 'O')  # opponent maximizes if player is X
            board[i] = None
            if player == 'X' and score > best_score:
                best_score = score; best = i
            elif player == 'O' and score < best_score:
                best_score = score; best = i
    return best

